function arrangeEvenOddIndexes(arr) {
  const result = Array(arr.length);
  let evenIndex = 0;
  let oddIndex = 1;

  for (const value of arr) {
    if (value % 2 === 0 && evenIndex < arr.length) {
      result[evenIndex] = value;
      evenIndex += 2;
    } else if (value % 2 !== 0 && oddIndex < arr.length) {
      result[oddIndex] = value;
      oddIndex += 2;
    }
  }

  return result;
}

